// Part 2 v5.6 terminal node: the migration built and its tests passed, or there are
// none. v5.4 made this node send an explicit `outcome`. v5.6 also assembles the
// report: the fact sections come from 'Collect Actual Changes' (the workspace diff,
// the job log, the plan compared with the final files) and the Reporter contributes
// only its Summary and Risks sections. Job 100's v5.5 report was the Reporter's text
// alone and claimed two changes that never happened.
const j = $input.first().json || {};
const llm = String(j.text || j.output || '');
let f = {};
try { f = $('Collect Actual Changes').first().json || {}; } catch (e) {}

// The backend cuts everything after ---TASKS--- into follow-up tasks, so the tasks
// block has to stay last.
const cut = llm.indexOf('---TASKS---');
const prose = (cut >= 0 ? llm.slice(0, cut) : llm).trim();
const tasks = cut >= 0 ? llm.slice(cut).trim() : '';
const section = (heading) => {
  const m = prose.match(heading);
  if (!m) return '';
  const rest = prose.slice(m.index + m[0].length);
  const next = rest.search(/^#{1,2}\s/m);
  return (next >= 0 ? rest.slice(0, next) : rest).trim();
};
const summary = section(/^#{1,3}\s*summary\b.*$/im);
const risks = section(/^#{1,3}\s*risks?\b.*$/im);

let report;
if (f.report_result_md) {
  const parts = [f.report_header, f.report_result_md];
  if (summary) parts.push('## Summary\n' + summary);
  // The model ignored the two-section format. Keep what it wrote, but say whose it is:
  // everything else in this report is generated from the workspace.
  else if (!risks && prose) parts.push("## Reporter's notes\n_Written by the model, not generated from the workspace._\n\n" + prose);
  parts.push(f.report_changes_md);
  if (risks) parts.push('## Risks and items for human review\n' + risks);
  parts.push(f.report_deferred_md);
  report = parts.filter(Boolean).join('\n\n');
} else {
  // Collect Actual Changes produced nothing usable: the v5.5 behaviour.
  report = prose;
}
if (tasks) report += '\n\n' + tasks;

// Keep every incoming field (downstream nodes and older backends read `text`).
return [{ json: Object.assign({}, j, {
  outcome: 'success',
  report: report,
  tests: ((f.report_facts || {}).tests) || 'unknown'
}) }];

// Part 2 v5.4 terminal node: the migrated code builds, but its tests fail.
// Reached from 'Test Gate' (false branch), whose input is Run Tests - which since
// v5.3 ends with the exit-code sentinel TESTS_FAILED.
// Until v5.4 this was an empty Set node, and the backend reported the run as
// "Workflow execution stopped unexpectedly", which is not what happened.
const j = $input.first().json || {};
const out = String(j.stdout || '');
const tail = out.split('\n').slice(-80).join('\n');
const report =
  '## Migration did not complete\n\n' +
  'The migrated code builds, but its tests fail, so no pull request should be opened. ' +
  'A compile-clean migration can still break behaviour at runtime - BinaryFormatter and ' +
  'Thread.Abort both compile on .NET 9 and throw when called - which is exactly what tests exist to catch.\n\n' +
  '### Test output (tail)\n\n' + tail;
return [{ json: { outcome: 'tests_failed', report: report, test_output: out } }];

// Part 2 v5.4 terminal node: the build still fails after the Error Fixer's last
// attempt. Reached from 'Max Retries Reached?', whose input is Store Build Output.
// Until v5.4 this was an empty Set node, and the backend only knew the run failed
// because the passed-through body happened to contain "BUILD_FAILED".
const j = $input.first().json || {};
const out = String(j.build_output || j.stdout || '');
const tail = out.split('\n').slice(-60).join('\n');
const report =
  '## Migration did not complete\n\n' +
  'The build still fails after the Error Fixer\'s last attempt, so no pull request should be opened. ' +
  'The workspace is left as the Error Fixer last had it.\n\n' +
  '### Last build output (tail)\n\n' + tail;
return [{ json: { outcome: 'build_failed', report: report, build_output: out } }];

