      SuccessRate: 100.0,
      RegressionRate: 0.0,
      NodeExecutions: nodeExecutions,
      Phase2Success: true,
      IsSuccess: true,
      LlmUsages: llmUsages
    },
    json: true
  });
} catch (e) {}
return $input.all();

