// Source for the Part 2 'Build Action List' Code node. Kept as a real .js file
// so it is readable and lintable; patch_v52_part2.js injects it verbatim.
//
// This was an LLM (chainLlm + Migrator LLM) until v5.2, which meant a model
// re-typing old/new snippets Part 1 had already produced and verified
// byte-exact (job 99: 16/16 matched). Every re-emission was a chance to
// paraphrase, truncate or mis-escape a string that /api/files/replace matches
// literally. The mapping needs no intelligence, so it does not get any.
//
// Emits the same two shapes 'Switch Action' routes on, so nothing downstream changes.

const body = $('Execute Webhook').first().json.body;
const tfm = body.target_framework || 'net8.0';
// /api/files/read uses GetInt32: a string jobId throws, and RepoLocator then
// serves a DIFFERENT job's workspace. Always send a number.
const jobId = Number(body.job_id);

let plan;
try {
  plan = typeof body.migration_plan === 'string' ? JSON.parse(body.migration_plan) : body.migration_plan;
} catch (e) {
  throw new Error('migration_plan is not valid JSON: ' + e.message);
}
if (!plan || typeof plan !== 'object') throw new Error('migration_plan is empty');

const actions = [];
const skipped = [];
const rel = (p) => String(p || '').replace(/^\/?projects\/migration-\d+\//, '').replace(/^\//, '').trim();

// The plan states the same edit in more than one place: a csproj TargetFramework
// bump appears in BOTH target_framework_updates and file_changes. Emitting both
// means the second always fails, because the first already changed the text.
const seenReplace = new Set();
function pushReplace(filePath, targetContent, replacementContent) {
  const key = filePath + '::' + String(targetContent).replace(/\s+/g, ' ').trim();
  if (seenReplace.has(key)) return false;
  seenReplace.add(key);
  actions.push({ action: 'ReplaceFileContent', filePath, targetContent, replacementContent });
  return true;
}

// ── 1. target framework ────────────────────────────────────────────────────
for (const t of (plan.target_framework_updates || [])) {
  const filePath = rel(t.file || t.file_path);
  // Verbatim, not trimmed: the plan carries the exact indented line and the
  // backend matches literally.
  const from = t.from !== undefined ? String(t.from) : '';
  const to = t.to !== undefined ? String(t.to) : '';
  if (!filePath || !from.trim() || !to.trim()) {
    skipped.push('target_framework_updates: incomplete entry for ' + (filePath || '?'));
    continue;
  }
  pushReplace(filePath, from, to);
}

// ── 2. file changes ────────────────────────────────────────────────────────
// old/new are copied verbatim. Changing them here reintroduces the paraphrase risk.
for (const f of (plan.file_changes || [])) {
  const filePath = rel(f.file || f.file_path);
  if (!filePath) { skipped.push('file_changes: entry with no file path'); continue; }
  for (const ch of (f.changes || [])) {
    const targetContent = ch.old !== undefined ? ch.old : ch.old_content;
    const replacementContent = ch.new !== undefined ? ch.new : ch.new_content;
    if (typeof targetContent !== 'string' || !targetContent.length) {
      skipped.push(filePath + ': change with empty targetContent (' + String(ch.reason || 'no reason given').slice(0, 60) + ')');
      continue;
    }
    if (typeof replacementContent !== 'string') {
      skipped.push(filePath + ': change with no replacement content');
      continue;
    }
    pushReplace(filePath, targetContent, replacementContent);
  }
}

// ── 3. startup changes ─────────────────────────────────────────────────────
for (const s of (plan.startup_changes || [])) {
  const filePath = rel(s.file || s.file_path);
  const targetContent = s.old !== undefined ? s.old : s.old_content;
  const replacementContent = s.new !== undefined ? s.new : s.new_content;
  if (!filePath || typeof targetContent !== 'string' || !targetContent.length || typeof replacementContent !== 'string') {
    skipped.push('startup_changes: incomplete entry for ' + (filePath || '?'));
    continue;
  }
  pushReplace(filePath, targetContent, replacementContent);
}

// ── 4. packages ────────────────────────────────────────────────────────────
// Never ReplaceFileContent a csproj for packages: dotnet keeps the file
// consistent and fails loudly on a bad version, where a string edit would not.
const FRAMEWORK_REFS = ['microsoft.netcore.app', 'microsoft.aspnetcore.app', 'microsoft.windowsdesktop.app'];
const allProjects = (plan.target_framework_updates || []).map((t) => rel(t.file || t.file_path)).filter(Boolean);

// Merge the two package sources by name. They overlap - job 99 listed the same
// five packages in package_updates AND nuget_versions_needed - and emitting both
// produced two identical `dotnet add` commands per package per project.
const pkgByName = new Map();
function addRow(name, version, action, project, fromUpdates) {
  const key = String(name || '').trim().toLowerCase();
  if (!key) return;
  // package_updates wins: it is the list NuGet Version Lookup re-pinned.
  if (pkgByName.has(key) && !fromUpdates) return;
  pkgByName.set(key, { name: String(name).trim(), version, action: action || 'update', project });
}
for (const u of (plan.package_updates || [])) {
  addRow(u.name, u.resolved_version || u.to_version, u.action, u.project || u.project_path, true);
}
for (const u of (plan.nuget_versions_needed || [])) {
  addRow(u.package || u.name, u.resolved_version || u.version, u.action, u.project || u.project_path, false);
}

// Which project actually references each package? Read the csproj files rather
// than guessing. Falling back to "every project" added RestSharp to LegacyWebApi,
// which never referenced it, and that spurious dependency shows up in the PR.
const projectRefs = new Map();
const PKG_REF = /<PackageReference\s+Include="([^"]+)"/g;
for (const proj of allProjects) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://host.docker.internal:5153/api/files/read',
      body: { jobId: jobId, filePath: proj },
      json: true
    });
    const content = String((typeof res === 'string') ? res : (res.content || res.Content || ''));
    let m;
    PKG_REF.lastIndex = 0;
    while ((m = PKG_REF.exec(content)) !== null) {
      const k = m[1].toLowerCase();
      if (!projectRefs.has(k)) projectRefs.set(k, []);
      projectRefs.get(k).push(proj);
    }
  } catch (e) {
    skipped.push('could not read ' + proj + ' to see which packages it references (' + e.message + ')');
  }
}

// The command TEMPLATE below is fixed code, but the package name, version and
// project path inside it come from Part 1's plan - LLM-written, and for a
// `remove` entry never even resolved against nuget.org. Everything here goes to
// `sh -c` through API ExecuteCommand, so admit only plain tokens. Same
// allowlists as the Error Fixer's manage_package tool.
const SAFE_ID = /^[A-Za-z0-9._-]+$/;
const SAFE_VERSION = /^[A-Za-z0-9.*+-]+$/;
const SAFE_PROJECT = /^[A-Za-z0-9._\/ -]+\.csproj$/i;

for (const p of pkgByName.values()) {
  const lower = p.name.toLowerCase();
  if (!SAFE_ID.test(p.name)) {
    skipped.push(JSON.stringify(p.name).slice(0, 60) + ': not a valid package id, refused (it would reach a shell)');
    continue;
  }
  if (FRAMEWORK_REFS.indexOf(lower) !== -1) {
    skipped.push(p.name + ': implicit framework reference, never added as a package');
    continue;
  }
  let targets = rel(p.project) ? [rel(p.project)] : (projectRefs.get(lower) || []);
  if (!targets.length) {
    if (p.action === 'remove') {
      skipped.push(p.name + ': marked for removal but no project references it');
      continue;
    }
    // A genuinely new package: nothing references it yet. Fall back to every
    // project and say so, rather than picking one silently.
    targets = allProjects;
    if (targets.length > 1) {
      skipped.push(p.name + ': not referenced by any project; added to all ' + targets.length + ' - check this is intended');
    }
  }
  if (!targets.length) {
    skipped.push(p.name + ': no project file known, cannot emit a dotnet command');
    continue;
  }

  for (const t of targets) {
    if (!SAFE_PROJECT.test(t)) {
      skipped.push(JSON.stringify(t).slice(0, 80) + ': not a plain .csproj path, refused (it would reach a shell)');
      continue;
    }
    if (p.action === 'remove') {
      actions.push({ action: 'ExecuteCommand', command: 'dotnet remove "' + t + '" package ' + p.name });
    } else {
      let v = String(p.version || '').trim();
      if (!v || v === 'incompatible' || v === 'lookup-failed') {
        skipped.push(p.name + ': no resolved version (' + (v || 'empty') + '), not added');
        continue;
      }
      if (/\.x$/i.test(v)) v = v.replace(/\.x$/i, '.*');
      if (!SAFE_VERSION.test(v)) {
        skipped.push(p.name + ': version ' + JSON.stringify(v).slice(0, 40) + ' is not a plain version string, refused');
        continue;
      }
      actions.push({ action: 'ExecuteCommand', command: 'dotnet add "' + t + '" package ' + p.name + ' --version ' + v });
    }
  }
}

// ── report ─────────────────────────────────────────────────────────────────
const counts = actions.reduce((a, x) => { a[x.action] = (a[x.action] || 0) + 1; return a; }, {});
let msg = 'Built ' + actions.length + ' execution step(s) deterministically from the plan for ' + tfm +
          ' (' + Object.keys(counts).map((k) => k + ': ' + counts[k]).join(', ') + ').';
if (skipped.length) msg += ' ' + skipped.length + ' entr(y/ies) skipped or flagged.';

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:5153/api/migrationjob/' + jobId + '/logs',
    body: {
      level: skipped.length ? 'warning' : 'info',
      phase: 'Execute',
      message: msg,
      details: skipped.length ? 'Skipped or flagged:\n- ' + skipped.join('\n- ') : null
    },
    json: true
  });
} catch (e) {}

if (!actions.length) {
  throw new Error('The plan produced no executable steps. ' +
    (skipped.length ? 'Skipped: ' + skipped.join(' | ') : 'The plan may be empty, or filtered to nothing.'));
}

return actions.map((a) => ({ json: a }));

// /api/files/replace answers 200 with { success: false } when the snippet does
// not match - it is not an HTTP error. Until v5.2 this node's output went
// straight back into the loop, so a failed edit was invisible: the run carried
// on, and the only trace was a build error the Error Fixer had to rediscover
// with no idea a planned step had been skipped.
//
// This does not abort. One unmatched snippet should not discard the rest of a
// migration; the build and the Error Fixer are the recovery path. It makes the
// failure loud instead of silent.
const out = [];
// Which file each result is about: API ReplaceFileContent answers one item per
// Switch Action item, in order. Without it the log said only that SOME edit failed.
let steps = [];
try { steps = $('Switch Action').all(); } catch (e) {}
for (const [idx, item] of $input.all().entries()) {
  const j = item.json || {};
  const ok = j.success === true || j.Success === true;
  if (!ok) {
    const msg = j.message || j.Message || 'unknown reason';
    const file = String((((steps[idx] || {}).json) || {}).filePath || '');
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: 'http://host.docker.internal:5153/api/migrationjob/' + $('Execute Webhook').first().json.body.job_id + '/logs',
        body: { level: 'error', phase: 'Execute',
                message: 'A planned file edit did not apply' + (file ? ' (' + file + ')' : '') + ': ' + msg,
                details: 'The build that follows may fail for this reason. If it says the target content was not found, the plan snippet no longer matches the file - most often because an earlier step in this same run already changed those lines.' },
        json: true
      });
    } catch (e) {}
  }
  out.push({ json: Object.assign({}, j, { replace_applied: ok }) });
}
return out;

// Error Fixer tool: read source. Replaces the old design where 'Run Build'
// cat'd EVERY file with an error into the prompt whether the model needed it
// or not - the whole dump then sat in context for the rest of the run.
const helpers = this.helpers;
const filePath = String(query.filePath || '').trim();
if (!filePath) return 'ERROR: filePath is required.';

const clean = filePath.replace(/^\/?projects\/migration-\d+\//, '').replace(/^\//, '');
// jobId must be a NUMBER: the backend parses it with GetInt32, and a string makes
// it fall back to RepoLocator.GetLatestRepo(), i.e. a different job's workspace.
const jobId = Number($('Execute Webhook').first().json.body.job_id);

try {
  const res = await helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:5153/api/files/read',
    body: {
      jobId: jobId,
      filePath: clean,
      startLine: query.startLine || 1,
      maxLines: Math.min(query.maxLines || 250, 400)
    },
    json: true
  });
  const content = (typeof res === 'string') ? res : (res.content || res.Content || JSON.stringify(res));
  return '--- ' + clean + ' ---\n' + content;
} catch (e) {
  // v5.5: on job 100 the Error Fixer asked for a non-existent
  // LegacyMvcApp/Utils/RestClient.cs 18 times in a row, because "could not read"
  // gave it nothing else to try. Say plainly that the file does not exist and
  // offer the real files nearby.
  let suggestions = '';
  try {
    const list = await helpers.httpRequest({
      method: 'POST',
      url: 'http://host.docker.internal:5153/api/files/list',
      body: { jobId: jobId },
      json: true
    });
    const files = (list && (list.files || list.Files)) || [];
    const dir = clean.indexOf('/') > -1 ? clean.slice(0, clean.lastIndexOf('/') + 1) : '';
    const base = clean.slice(clean.lastIndexOf('/') + 1).toLowerCase().replace(/\.[^.]+$/, '');
    const sameDir = files.filter((f) => dir && f.indexOf(dir) === 0 && f.slice(dir.length).indexOf('/') === -1);
    const similar = files.filter((f) => base && f.toLowerCase().indexOf(base) > -1 && sameDir.indexOf(f) === -1);
    const pick = sameDir.concat(similar).slice(0, 25);
    if (pick.length) suggestions = '\nFiles that DO exist' + (dir ? ' in ' + dir + ' or with a similar name' : '') + ':\n- ' + pick.join('\n- ');
  } catch (e2) {}
  return 'NOT FOUND: ' + clean + ' does not exist in this repository (' + e.message + '). ' +
    'Do not request this path again.' + suggestions;
}

