// Error Fixer tool: overwrite a whole file. The "nuclear option" of the v5.x
// prompt, kept because it is the only sane fix for unbalanced brackets - a
// targeted replace tends to miss a trailing brace at the end of the file.
const helpers = this.helpers;
const filePath = String(query.filePath || '').trim();
const content = query.content;
if (!filePath) return 'ERROR: filePath is required.';
if (typeof content !== 'string' || !content.length) {
  return 'ERROR: content must be the COMPLETE new file, top to bottom. Refusing to write an empty file.';
}

const clean = filePath.replace(/^\/?projects\/migration-\d+\//, '').replace(/^\//, '');

try {
  const res = await helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:5153/api/files/write',
    body: {
      jobId: Number($('Execute Webhook').first().json.body.job_id),
      filePath: clean,
      content: content
    },
    json: true
  });
  const ok = res && (res.success === true || res.Success === true);
  return ok
    ? 'OK: rewrote ' + clean + ' (' + content.split('\n').length + ' lines).'
    : 'FAILED on ' + clean + ': ' + ((res && (res.message || res.Message)) || 'unknown reason');
} catch (e) {
  return 'FAILED on ' + clean + ': ' + e.message;
}

