    "packageId"
  ]
}

parameters.jsCode:
// Source for the Part 2 'Prepare Error Fixer Context' Code node (v5.5). Runs before
// every Error Fixer attempt and hands it three things it did not have on job 100,
// where it failed a one-line fix three times in 20.5 minutes:
//
//  1. The planned edits whose intended code is NOT in the file. The failed AutoMapper
//     edit's new code contained exactly the right call, but v5.3 had dropped the
//     plan from the prompt. Only the edits still missing, not the whole plan.
//  2. The previous attempts: what each said it changed and the errors that followed.
//     Attempt 3 did not know attempt 2's `using` was the thing that had just failed.
//     Read from the job log (GET /logs is anonymous), which already stores each
//     summary and each build's output - deterministic and testable.
//  3. The repository's real files, so it stops inventing paths (it asked for a
//     non-existent RestClient.cs 18 times).
//
// Every source is best-effort: if one fails, that section is omitted and the
// attempt proceeds as it would have in v5.4.
const helpers = this.helpers;
const body = $('Execute Webhook').first().json.body;
const jobId = Number(body.job_id);
const API = 'http://host.docker.internal:5153';

const clip = (s, n) => { s = String(s || ''); return s.length <= n ? s : s.slice(0, n) + '\n...[truncated]'; };
const norm = (s) => String(s || '').replace(/\r\n/g, '\n').split('\n').map((l) => l.trim()).filter(Boolean).join('\n');
const errorLines = (text) => {
  const seen = new Set(), out = [];
  for (const line of String(text || '').split('\n')) {
    const m = line.match(/([^\s]*\.(?:cs|csproj)\(\d+,\d+\))\s*:\s*error\s+([A-Z]+\d+)\s*:\s*([^[]*)/);
    if (!m) continue;
    const e = m[1].replace(/^.*\/projects\/migration-\d+\//, '') + ': error ' + m[2] + ': ' + m[3].trim();
    if (!seen.has(e)) { seen.add(e); out.push(e); }
  }
  return out;
};
const sections = [];

// ── 1. planned edits whose intended code is not in the file ─────────────────
try {
  const planned = $('Build Action List').all().map((i) => i.json)
    // .csproj edits are excluded: TFM and packages are applied by other steps
    // (target_framework_updates, dotnet add/remove), and a whole-file csproj
    // rewrite from the plan would reintroduce packages the reviewer deferred.
    .filter((a) => a.action === 'ReplaceFileContent' && !/\.csproj$/i.test(a.filePath));
  const files = {};
  const missing = [];
  for (const a of planned) {
    if (!(a.filePath in files)) {
      try {
        const r = await helpers.httpRequest({ method: 'POST', url: API + '/api/files/read',
          body: { jobId: jobId, filePath: a.filePath }, json: true });
        files[a.filePath] = String(r.content || r.Content || '');
      } catch (e) { files[a.filePath] = null; }
    }
    const current = files[a.filePath];
    if (current === null) continue;
    if (norm(current).indexOf(norm(a.replacementContent)) !== -1) continue;   // intent is present
    missing.push(a);
  }
  if (missing.length) {
    let s = 'PLANNED EDITS WHOSE INTENDED CODE IS NOT IN THE FILE\n' +
      'The migration plan wanted the files below to end up containing this code, and it is not there - ' +
      'usually because the edit failed to apply. It is the best available reference for the correct fix: ' +
      'bring the CURRENT file (read it first) to this intent. Do not paste it blindly over code that has since changed.\n';
    let budget = 14000;
    for (const a of missing) {
      const block = '\n### ' + a.filePath + '\n' + clip(a.replacementContent, 5000) + '\n';
      if (block.length > budget) { s += '\n(' + (missing.length) + ' edits in total; the rest omitted for length)\n'; break; }
      s += block; budget -= block.length;
    }
    sections.push(s);
  }
} catch (e) {}

// ── 2. previous attempts in this run, from the job log ──────────────────────
try {
  const logs = await helpers.httpRequest({ method: 'GET', url: API + '/api/migrationjob/' + jobId + '/logs', json: true });
  const all = Array.isArray(logs) ? logs : [];
  let start = -1;
  all.forEach((l, i) => { if (l.message === 'Started Execution Phase.') start = i; });
  const run = start >= 0 ? all.slice(start) : [];
  const attempts = [];
  run.forEach((l, i) => {
    if (!/^Error Fixer /.test(String(l.message || ''))) return;
    const next = run.slice(i + 1).find((x) => x.message === 'Build executed.');
    attempts.push({ summary: String(l.details || '').trim(), after: next ? errorLines(next.details) : null });
  });
  if (attempts.length) {
    let s = 'PREVIOUS ATTEMPTS IN THIS RUN - they did not fix the build. Do not repeat an approach that already failed.\n';
    attempts.forEach((a, k) => {
      s += '\nAttempt ' + (k + 1) + ' said:\n' + clip(a.summary || '(no summary was recorded)', 1500) + '\n' +
        'Errors after attempt ' + (k + 1) + ':\n' +
        (a.after === null ? '(build result not recorded)' : (a.after.length ? a.after.join('\n') : '(no compiler errors parsed)')) + '\n';
    });
    sections.push(s);
  }
} catch (e) {}

// ── 3. the repository's real files ──────────────────────────────────────────
try {
  const r = await helpers.httpRequest({ method: 'POST', url: API + '/api/files/list', body: { jobId: jobId }, json: true });
  const files = ((r && (r.files || r.Files)) || []).filter((f) => !/\.(png|jpe?g|gif|ico|svg|woff2?|ttf|eot|map|min\.js|min\.css)$/i.test(f));
  if (files.length) {
    sections.push('REPOSITORY FILES - these are the only files that exist. Never request a path that is not listed.\n' +
      clip(files.join('\n'), 6000));
  }
} catch (e) {}

const ef_context = sections.length ? sections.join('\n\n') : '';
return [{ json: Object.assign({}, $input.first().json, { ef_context: ef_context, ef_context_sections: sections.length }) }];

// Error Fixer tool: Microsoft Learn search. Same capped implementation as Part 1's
// 'MS Learn Docs' node (v6.8), copied verbatim. Added because on job 100 the Error
// Fixer guessed NullLoggerFactory's namespace (wrong) with no way to look it up -
// one search answers it. In Part 2 the desktop-detection lookup of 'Run Roslyn
// Upgrade Assistant' throws inside its try, so desktop results are filtered.

// microsoft_docs_search over the MCP HTTP endpoint. The endpoint is stateless
// (no initialize handshake, no session id) and SSE-framed, so parse "data: ".
//
// A raw search is ~20-24k chars / 10 results. Every result lands in the ReAct
// scratchpad and is re-sent on every later turn, so cap the bodies and keep the
// metadata: contentUrl is the only part the brief actually cites.
const q = String(query.query || '').trim();
if (!q) return 'ERROR: query is required.';

const CAP = 700;

// Only drop desktop-stack hits when this repo is not itself a desktop project.
let isDesktop = false;
try {
  const dump = $('Run Roslyn Upgrade Assistant').first().json.stdout || '';
  isDesktop = /<UseWPF>|<UseWindowsForms>|Microsoft\.NET\.Sdk\.WindowsDesktop/i.test(dump);
} catch (e) {}
const DESKTOP = /\/desktop\/winforms|\/wpf|\/xamarin|\/maui|winforms-applications|wpf-applications/i;

// A toolCode node that catches its own errors can never trigger n8n's
// retryOnFail, so the v6.4 retry policy this node used to carry as an
// mcpClientTool has to be re-implemented here. 'fetch failed' is undici's
// "connection never got off the ground" and is exactly the blip worth retrying.
const helpers = this.helpers;
async function callMcp(toolName, args) {
  let lastErr;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      return await helpers.httpRequest({
        method: 'POST',
        url: 'https://learn.microsoft.com/api/mcp',
        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
        body: { jsonrpc: '2.0', id: 1, method: 'tools/call', params: { name: toolName, arguments: args } },
        json: false
      });
    } catch (e) {
      lastErr = e;
      if (attempt < 3) await new Promise(function (r) { setTimeout(r, 2000 * attempt); });
    }
  }
  throw lastErr;
}

try {
  const res = await callMcp('microsoft_docs_search', { query: q });
  const line = String(res).split('\n').find(function (l) { return l.indexOf('data: ') === 0; });
  if (!line) return 'MS Learn returned no parsable payload for "' + q + '".';
  const all = JSON.parse(JSON.parse(line.slice(6)).result.content[0].text).results || [];
  if (!all.length) return 'No Microsoft Learn results for "' + q + '".';

  const kept = isDesktop ? all : all.filter(function (r) { return !DESKTOP.test(r.contentUrl || ''); });
  const use = kept.length ? kept : all;
  const dropped = all.length - use.length;

  let out = use.map(function (r) {
    return r.title + '\n' + r.contentUrl + '\n' + String(r.content || '').slice(0, CAP);
  }).join('\n---\n');
  if (dropped) {
    out += '\n---\n(' + dropped + ' desktop-stack result(s) omitted: this is not a WinForms/WPF project)';
  }
  out += '\n\n(Excerpts are capped at ' + CAP + ' chars. If you need a type full member list to verify a replacement, call fetch_ms_learn_page on its contentUrl. Do that sparingly: it is the most expensive call available.)';
  return out;
} catch (e) {
  return 'MS Learn search failed for "' + q + '": ' + e.message;
}

// Error Fixer tool: grep the repository. Part 1's 'Grep Repo', retargeted to Part 2's
// 'Execute Webhook'. The v5.3 prompt already told the Error Fixer to grep for call
// sites, but it had no grep tool until v5.5. jobId is sent as a NUMBER - see read_file.js.

const jobId = Number($('Execute Webhook').first().json.body.job_id);
const pattern = String(query.pattern || '').trim();
if (!pattern) return 'ERROR: pattern is required.';

try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:5153/api/files/grep',
    body: {
      jobId: jobId,
      pattern: pattern,
      glob: query.glob || '*.cs',
      maxResults: Math.min(query.maxResults || 40, 100)
    },
    json: true
  });
  const matches = res.matches || res.Matches || [];
  if (!matches.length) return `No matches for "${pattern}" in ${query.glob || '*.cs'}.`;
  return matches.map(m => `${m.filePath || m.FilePath}:${m.lineNumber || m.LineNumber}: ${(m.line || m.Line || '').trim()}`).join('\n');
} catch (e) {
  return `Grep failed for "${pattern}": ${e.message}`;
}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "pattern": {
      "type": "string",
      "description": "Regex or literal string to search for"
    },
    "glob": {
      "type": "string",
      "description": "File glob, default *.cs (use *.csproj for project files)"
    },
    "maxResults": {
      "type": "number",
      "description": "Max matches to return (default 40, max 100)"
    }
  },
  "required": [
    "pattern"
  ]
}

parameters.jsCode:
// Error Fixer tool: build the workspace and report the errors.
//
// v5.5. On job 100 every attempt ended "The build error is fixed" without having
// built anything; the outer loop then built, failed, and started a FRESH agent.
// With this the agent verifies inside its own attempt and sees the compiler's
// answer to each edit.
//
// A toolCode node cannot run a shell, and the backend's /api/build is unusable here
// (it builds GetLatestRepo(), not a given job, and on the host rather than the
// container). So the build runs in n8n itself, in a small separate workflow
// ('DotNet Migration Build Tool') behind a fixed webhook path - same container, same
// SDKs, same /projects mount as 'Run Build'. That workflow must be imported and
// ACTIVE; if it is not, this tool says so and the agent carries on without it.
const helpers = this.helpers;
const jobId = Number($('Execute Webhook').first().json.body.job_id);

let res;
try {
  res = await helpers.httpRequest({
    method: 'POST',
    url: 'http://localhost:5678/webhook/migration-build-tool',
    body: { jobId: jobId },
    json: true,
    timeout: 400000
  });
} catch (e) {
  return 'BUILD TOOL UNAVAILABLE (' + e.message + '). The \'DotNet Migration Build Tool\' workflow is probably not ' +
    'imported or not active. Continue without it; the pipeline builds again after you finish.';
}

const out = String((res && (res.stdout || res.output)) || (typeof res === 'string' ? res : ''));
if (!out.trim()) {
  return 'BUILD TOOL returned nothing - it probably failed inside n8n. Continue without it.';
}
if (/BUILD_SUCCESS\s*$/.test(out.trim())) {
  return 'BUILD SUCCEEDED: 0 errors. The fix works - stop editing and write your summary.';
}

// dotnet prints each diagnostic twice (while building and in the summary), with
// absolute container paths. Deduplicate and make paths repo-relative.
const seen = new Set();
const errors = [];
for (const line of out.split('\n')) {
  const m = line.match(/([^\s]*\.(?:cs|csproj|sln|props|targets)\(\d+,\d+\)|[^\s]*\.csproj)\s*:\s*error\s+([A-Z]+\d+)\s*:\s*([^[]*)/);
  if (!m) continue;
  const where = m[1].replace(/^.*\/projects\/migration-\d+\//, '');
  const key = where + m[2] + m[3].trim();
  if (seen.has(key)) continue;
  seen.add(key);
  errors.push(where + ': error ' + m[2] + ': ' + m[3].trim());
}
if (!errors.length) {
  const tail = out.trim().split('\n').slice(-15).join('\n');
  return 'BUILD FAILED, but no compiler errors could be parsed. Last lines:\n' + tail;
}
return 'BUILD FAILED: ' + errors.length + ' error(s)\n' + errors.slice(0, 40).join('\n') +
  (errors.length > 40 ? '\n...and ' + (errors.length - 40) + ' more' : '');

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "reason": {
      "type": "string",
      "description": "Optional: what you expect this build to confirm"
    }
  }
}

parameters.jsCode:
// Source for the Part 2 'Collect Actual Changes' Code node (v5.6). Runs before the
// Reporter and gathers what the migration actually DID, so the report stops
// describing the plan. Job 100's v5.5 report was written from the plan and the build
// output alone. It claimed two changes that never happened - a "repaired corrupted
// field name" that existed only in the plan's deliberately broken snippet, and a
// MailKit reference no project has - and said "Tests: PASSED" for a solution with
// no tests.
//
// Everything here is deterministic: the workspace diff (POST /api/files/diff), this
// run's job log, the plan's edits compared with the final files, and the outputs of
// the test and CVE steps. It renders the report's fact sections; the Reporter now
// writes only the summary and the risks, and Success Response puts them together.
// It also logs one line comparing the final code with the plan, which the backend
// quotes in the PR description.
//
// Every source is best-effort: a section whose source failed says so. If this node
// produces nothing, Success Response falls back to the Reporter's text alone.
const helpers = this.helpers;
const body = $('Execute Webhook').first().json.body;
const jobId = Number(body.job_id);
const API = 'http://host.docker.internal:5153';
const TFM = String(body.target_framework || 'net8.0');

const norm = (s) => String(s || '').replace(/\r\n/g, '\n').split('\n').map((l) => l.trim()).filter(Boolean).join('\n');
const clip = (s, n) => { s = String(s || '').trim(); return s.length <= n ? s : s.slice(0, n).trimEnd() + '…'; };
const code = (s) => '`' + String(s).replace(/`/g, "'") + '`';
const rel = (p) => String(p || '').replace(/^.*\/projects\/migration-\d+\//, '').replace(/^\.\//, '');
const isProj = (p) => /\.csproj$/i.test(String(p || ''));
const count = (n, one, many) => n + ' ' + (n === 1 ? one : (many || one + 's'));
const list = (x) => (Array.isArray(x) ? x : (x ? [x] : []));
const text = (x) => (typeof x === 'string' ? x : JSON.stringify(x));
const errorLines = (s) => {
  const seen = new Set(), found = [];
  for (const line of String(s || '').split('\n')) {
    const m = line.match(/([^\s]*\.(?:cs|csproj)\(\d+,\d+\))\s*:\s*error\s+([A-Z]+\d+)\s*:\s*([^[]*)/);
    if (!m) continue;
    const e = { file: rel(m[1].replace(/\(\d+,\d+\)$/, '')), code: m[2], line: rel(m[1]) + ': error ' + m[2] + ': ' + m[3].trim() };
    if (!seen.has(e.line)) { seen.add(e.line); found.push(e); }
  }
  return found;
};
// The planned code is in the file. When the replacement is empty or contained in the
// original (a deletion), finding it proves nothing - check the original is gone instead.
const intentPresent = (file, a) => {
  const f = norm(file), n = norm(a.replacementContent), o = norm(a.targetContent);
  if (!n || (o && o.indexOf(n) !== -1)) return !o || f.indexOf(o) === -1;
  return f.indexOf(n) !== -1;
};

try {
  let plan = {};
  try { plan = typeof body.migration_plan === 'string' ? JSON.parse(body.migration_plan) : (body.migration_plan || {}); } catch (e) {}
  const deferred = Array.isArray(body.deferred_changes) ? body.deferred_changes : [];

  // ── 1. this run's job log ───────────────────────────────────────────────────
  let run = null;
  try {
    const logs = await helpers.httpRequest({ method: 'GET', url: API + '/api/migrationjob/' + jobId + '/logs', json: true });
    const all = Array.isArray(logs) ? logs : [];
    let start = -1;
    all.forEach((l, i) => { if (l.message === 'Started Execution Phase.') start = i; });
    if (start >= 0) run = all.slice(start);
  } catch (e) {}
  const builds = (run || []).filter((l) => l.message === 'Build executed.');
  const attempts = (run || []).filter((l) => /^Error Fixer /.test(String(l.message || '')));
  // v5.6 names the file in brackets; v5.5 did not, and then it is null.
  const notApplied = (run || []).filter((l) => /^A planned file edit did not apply/.test(String(l.message || '')))
    .map((l) => { const m = String(l.message).match(/^A planned file edit did not apply \((.+?)\):/); return m ? rel(m[1]) : null; });

  // ── 2. the workspace diff ───────────────────────────────────────────────────
  let diff = null;
  try {
    const r = await helpers.httpRequest({ method: 'POST', url: API + '/api/files/diff', body: { jobId: jobId }, json: true });
    if (r && r.success) diff = r;
  } catch (e) {}

  // ── 3. the plan's edits compared with the final files ───────────────────────
  let actions = [];
  try { actions = $('Build Action List').all().map((i) => i.json); } catch (e) {}
  const plannedFiles = new Set();
  for (const a of actions) {
    if (a.action === 'ReplaceFileContent') plannedFiles.add(rel(a.filePath));
    const m = a.action === 'ExecuteCommand' && String(a.command || '').match(/dotnet (?:add|remove) "([^"]+)"/);
    if (m) plannedFiles.add(rel(m[1]));
  }
  // .csproj edits are not compared: target framework and packages are applied by
  // dotnet commands, not by the plan's text (section 4 reads them from the diff).
  const edits = actions.filter((a) => a.action === 'ReplaceFileContent' && !isProj(a.filePath));
  const current = {};
  const missing = [];
  let unreadable = 0;
  for (const a of edits) {
    const p = rel(a.filePath);
    if (!(p in current)) {
      try {
        const r = await helpers.httpRequest({ method: 'POST', url: API + '/api/files/read', body: { jobId: jobId, filePath: p }, json: true });
        current[p] = String(r.content || r.Content || '');
      } catch (e) { current[p] = null; }
    }
    if (current[p] === null) { unreadable++; continue; }
    if (!intentPresent(current[p], a)) missing.push(p);
  }
  const missingFiles = [...new Set(missing)];
  // A code edit that did not apply, in a file whose planned code is now all present:
  // the Error Fixer made it, since nothing else writes code after the planned steps.
  const recovered = notApplied.filter((p) => p && !isProj(p) && current[p] != null && !missingFiles.includes(p)).length;

  // ── 4. package and framework changes, from the .csproj diffs ────────────────
  const projChanges = [];
  if (diff && diff.diff) {
    for (const part of String(diff.diff).split(/^diff --git /m).slice(1)) {
      const m = part.split('\n')[0].match(/^a\/(.+?) b\/(.+)$/);
      const file = m ? m[2] : '';
      if (!isProj(file)) continue;
      const before = {}, after = {};
      let tfFrom = null, tfTo = null;
      for (const line of part.split('\n')) {
        if (!/^[-+]/.test(line) || /^(---|\+\+\+) /.test(line)) continue;
        const pr = line.match(/<PackageReference\s+Include="([^"]+)"(?:\s+Version="([^"]*)")?/i);
        if (pr) (line[0] === '-' ? before : after)[pr[1].toLowerCase()] = { name: pr[1], v: pr[2] || '' };
        const tf = line.match(/<TargetFrameworks?>\s*([^<]+?)\s*</i);
        if (tf) { if (line[0] === '-') tfFrom = tf[1]; else tfTo = tf[1]; }
      }
      const items = [];
      if (tfFrom || tfTo) items.push('target framework ' + code(tfFrom || '?') + ' → ' + code(tfTo || '?'));
      for (const k of [...new Set([...Object.keys(before), ...Object.keys(after)])]) {
        const b = before[k], a = after[k];
        if (b && a) { if (b.v !== a.v) items.push(a.name + ' ' + b.v + ' → ' + a.v); }
        else if (a) items.push(a.name + ' ' + a.v + ' added');
        else items.push(b.name + ' ' + b.v + ' removed');
      }
      if (items.length) projChanges.push(code(file) + ': ' + items.join('; '));
    }
  }

  // ── 5. tests and the CVE audit ──────────────────────────────────────────────
  let testOut = '', cveOut = '';
  try { testOut = String(($('Run Tests').first().json || {}).stdout || ''); } catch (e) {}
  try { cveOut = String(($('Security Patch CVE Check').first().json || {}).stdout || ''); } catch (e) {}
  const sentinel = testOut.trim().split('\n').pop().trim();
  const tests = sentinel === 'NO_TEST_PROJECT_FOUND' ? 'none' : sentinel === 'TESTS_PASSED' ? 'passed'
    : sentinel === 'TESTS_FAILED' ? 'failed' : 'unknown';
  // Display only - the gate uses the sentinel, never this wording.
  const totalTests = [...testOut.matchAll(/Total tests:\s*(\d+)/gi)].reduce((s, m) => s + Number(m[1]), 0);
  const vulnerable = [...cveOut.matchAll(/project [`'"]?([^`'"\s]+)[`'"]? has the following vulnerable packages/gi)].map((m) => m[1]);
  const clean = [...cveOut.matchAll(/project [`'"]?([^`'"\s]+)[`'"]? has no vulnerable packages/gi)].map((m) => m[1]);

  // ── 6. the fact sections ────────────────────────────────────────────────────
  const firstErrors = attempts.length && builds.length ? errorLines(builds[0].details) : [];
  let buildLine = '- **Build:** passes on ' + code(TFM) + ', confirmed by the pipeline\'s final `dotnet build`.';
  if (attempts.length) {
    buildLine += ' The first build failed' + (firstErrors.length
      ? ' with ' + count(firstErrors.length, 'error') + ' (' + [...new Set(firstErrors.map((e) => e.code))].map(code).join(', ') +
        ' in ' + [...new Set(firstErrors.map((e) => e.file))].map(code).join(', ') + ')'
      : '') + '; the Error Fixer made ' + count(attempts.length, 'attempt') + ' before it passed.';
  }
  const result = ['## Result', buildLine,
    { none: '- **Tests:** none. The solution has no test project, so nothing was tested.',
      passed: '- **Tests:** passed' + (totalTests ? ' (' + count(totalTests, 'test') + ')' : '') + '.',
      failed: '- **Tests:** failed.',
      unknown: '- **Tests:** the result was not recognised; see the job log.' }[tests],
    vulnerable.length
      ? '- **Known vulnerable packages:** reported in ' + vulnerable.map(code).join(', ') + ' by `dotnet list package --vulnerable`. Review before merging.'
      : clean.length
        ? '- **Known vulnerable packages:** none reported by `dotnet list package --vulnerable` (' + clean.map(code).join(', ') + ').'
        : '- **Known vulnerable packages:** could not be determined from the audit output.',
    '- **Scope:** only the changes required to build and run on ' + code(TFM) + ' were applied. ' + (deferred.length
      ? count(deferred.length, '"should" change') + ' ' + (deferred.length === 1 ? 'was' : 'were') + ' deferred and ' +
        (deferred.length === 1 ? 'is' : 'are') + ' still in the code; see Deferred.'
      : 'Nothing was deferred.')];

  const changes = ['## Changed files'];
  if (!diff) {
    changes.push('_The workspace diff could not be read, so the changed files cannot be listed here._');
  } else {
    changes.push('From `git diff` of the migrated workspace: the record of what actually changed.');
    const files = diff.files || [];
    const untracked = diff.untracked || [];
    if (!files.length && !untracked.length) changes.push('- No file differs from the original code.');
    for (const f of files) {
      const p = rel(f.path);
      let note = '';
      if (!plannedFiles.has(p)) note = ' — not in the plan: changed by the Error Fixer';
      else if (notApplied.includes(p) && !isProj(p) && !missingFiles.includes(p)) note = ' — its planned edit did not apply; the Error Fixer made the change';
      changes.push('- ' + code(p) + (f.added == null ? ' (binary)' : ' (+' + f.added + ' −' + f.removed + ')') + note);
    }
    for (const u of untracked) changes.push('- ' + code(rel(u)) + ' (new file) — not in the plan: created by the Error Fixer');
    changes.push('', '## Package and framework changes', 'From the `.csproj` diffs.');
    changes.push(...(projChanges.length ? projChanges.map((l) => '- ' + l) : ['- No project file changed.']));
  }

  changes.push('', '## Planned edits');
  if (notApplied.length) {
    const named = [...new Set(notApplied.filter(Boolean))];
    changes.push('- ' + count(notApplied.length, 'planned edit') + ' did not match the file when execution ran' +
      (named.length ? ': ' + named.map(code).join(', ') + '.' : ' (see the job log).'));
  }
  if (edits.length && unreadable < edits.length) {
    changes.push(missingFiles.length
      ? '- ⚠️ The intended code of ' + count(missing.length, 'planned edit') + ' is **not** in the final code: ' + missingFiles.map(code).join(', ') +
        '. The build passes, so the error was resolved some other way, or the change was lost. Compare these files with the plan before merging.'
      : '- Every planned code edit is in the final code' + (recovered ? '; ' + recovered + ' of them ' + (recovered === 1 ? 'was' : 'were') +
        ' made by the Error Fixer after the planned edit did not apply.' : '.'));
  } else if (!edits.length) {
    changes.push('- The plan had no code edits besides project files.');
  }
  if (unreadable) changes.push('- ' + count(unreadable, 'planned edit') + ' could not be checked: the file could not be read back.');
  if (actions.some((a) => a.action === 'ReplaceFileContent' && isProj(a.filePath))) {
    changes.push('- Project files are not compared with the plan\'s text: their target framework and packages are applied by `dotnet` commands and shown above.');
  }

  if (attempts.length) {
    changes.push('', '## Error Fixer',
      'The first build failed, so the Error Fixer ran. What it reported after each attempt, in its own words (not independently checked; the changed files above are the record):');
    attempts.forEach((a, k) => changes.push('', '**Attempt ' + (k + 1) + '**', ...clip(a.details || '(no summary recorded)', 900).split('\n').map((l) => '> ' + l)));
  }

  const deferredMd = ['## Deferred'];
  if (deferred.length) {
    deferredMd.push('These "should" changes were in the reviewed plan and were deliberately **not** applied; the code still contains them. ' +
      (deferred.some((d) => d.pragma_suppressed) ? '🔇 marks a change whose compiler warning is suppressed by `#pragma`, so the clean build does not show it.' : ''));
    for (const d of deferred) deferredMd.push('- ' + (d.pragma_suppressed ? '🔇 ' : '') + code(d.target) + ' — ' + clip(d.reason, 220));
  } else {
    deferredMd.push('No planned change was deferred.');
  }

  // ── 7. what the Reporter gets: intent without code, and the real diff ────────
  const digest = ['Source framework: ' + (plan.source_framework || 'unknown') + '. Target: ' + TFM + '. Plan risk level: ' + (plan.risk_level || 'unknown') + '.'];
  const fc = list(plan.file_changes);
  if (fc.length) {
    digest.push('Planned code changes (intent only - the diff shows what happened):');
    for (const f of fc) for (const c of list(f.changes)) digest.push('- ' + (f.file || f.file_path) + ': ' + clip(c.reason || c.description || '', 220));
  }
  for (const [title, items, n] of [['Plan risk notes:', plan.risk_notes, 500], ['NuGet warnings:', plan.nuget_warnings, 300], ['Known vulnerabilities in the original packages:', plan.nuget_vulnerabilities, 300]]) {
    if (list(items).length) { digest.push(title); list(items).forEach((r) => digest.push('- ' + clip(text(r), n))); }
  }
  let diffForLlm = '(the workspace diff could not be read)';
  if (diff) {
    diffForLlm = clip(diff.diff || '(no changes)', 24000);
    if ((diff.diff || '').length > 24000 || diff.truncated) diffForLlm += '\n[diff truncated]';
    if ((diff.untracked || []).length) diffForLlm += '\nNew files not shown in the diff: ' + diff.untracked.join(', ');
  }

  // ── 8. one log line for the dashboard terminal and the PR description ──────
  if (edits.length && unreadable < edits.length) {
    const message = 'Compared the final code with the plan: ' + (missingFiles.length
      ? count(missing.length, 'planned code edit') + ' ' + (missing.length === 1 ? 'is' : 'are') + ' NOT in the final code, in ' + missingFiles.join(', ') + '.'
      : 'every planned code edit is in the final code' + (recovered ? ' (' + recovered + ' made by the Error Fixer after the planned edit did not apply)' : '') + '.');
    try {
      await helpers.httpRequest({ method: 'POST', url: API + '/api/migrationjob/' + jobId + '/logs', json: true,
        body: { level: missingFiles.length || unreadable ? 'warning' : 'info', phase: 'Execute', message: message,
                details: edits.map((a) => rel(a.filePath) + ': ' + (current[rel(a.filePath)] === null ? 'not readable' : missing.includes(rel(a.filePath)) ? 'NOT in the final code' : 'in the final code')).join('\n') } });
    } catch (e) {}
  }

  return [{ json: Object.assign({}, $input.first().json, {
    report_header: '# Migration report — ' + (plan.source_framework || 'current framework') + ' → ' + TFM,
    report_result_md: result.join('\n'),
    report_changes_md: changes.join('\n'),
    report_deferred_md: deferredMd.join('\n'),
    report_plan_digest: digest.join('\n'),
    report_diff: diffForLlm,
    report_facts: { tests: tests, total_tests: totalTests, vulnerable_projects: vulnerable, changed_files: diff ? (diff.files || []).length : null,
                    planned_code_edits: edits.length, missing_code_edits: missingFiles, edits_not_applied: notApplied.length,
                    recovered_by_error_fixer: recovered, error_fixer_attempts: attempts.length, diff_available: !!diff, job_log_available: !!run }
  }) }];
} catch (e) {
  // Never block the report: Success Response falls back to the Reporter's text.
  return [{ json: Object.assign({}, $input.first().json, { report_error: String((e && e.message) || e) }) }];
}
